SELECT 
FROM people_medication
WHERE tenant_id = #{tenantId}
  AND people_id = #{peopleId}
  AND is_deleted = 0

  AND status = #{status}

ORDER BY COALESCE(start_date, gmt_created) DESC, gmt_created DESC

SELECT FROM people_medication WHERE tenant_id = #{tenantId} AND is_deleted = 0 AND status = 'ACTIVE' AND (stop_date IS NULL OR stop_date >= CURDATE()) AND people_id IN
#{pid}
ORDER BY people_id, COALESCE(start_date, gmt_created) DESC
